import{_ as t,o as d,c as a,ag as o}from"./chunks/framework.DCKC-kU_.js";const m=JSON.parse('{"title":"Current v1alpha2 Form candidates","description":"","frontmatter":{},"headers":[],"relativePath":"forms/index.md","filePath":"forms/index.md"}'),r={name:"forms/index.md"};function c(n,e,i,s,l,u){return d(),a("div",null,[...e[0]||(e[0]=[o('<h1 id="current-v1alpha2-form-candidates" tabindex="-1">Current v1alpha2 Form candidates <a class="header-anchor" href="#current-v1alpha2-form-candidates" aria-label="Permalink to &quot;Current v1alpha2 Form candidates&quot;">​</a></h1><p>This is the provider-v2 source candidate inventory for the nine Form-backed Resources currently operated by Takosumi Cloud. Every entry is a local Proposal-derived publication candidate under <code>forms.takoform.com/v1alpha2</code>, awaiting an explicit lifecycle transition before Experimental; none is published, Experimental, Stable, centrally approved, or guaranteed commercially available. Each contract describes what a caller wants without naming a target, credential, placement, price, or implementation. A host may publish support and activate an exact FormRef under its own policy.</p><p>The frozen v1alpha1 inventory remains verifiable through <a href="standard-package-set.json"><code>standard-package-set.json</code></a> and immutable release sources, but it is not rendered as the current provider catalog.</p><h2 id="compute-and-application" tabindex="-1">Compute and application <a class="header-anchor" href="#compute-and-application" aria-label="Permalink to &quot;Compute and application&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Kind</th><th>Resource</th><th>Version</th><th>Portable intent</th></tr></thead><tbody><tr><td><code>EdgeWorker</code></td><td><code>takoform_edge_worker</code></td><td><code>0.1.0</code></td><td>Portable request/event application executed from digest-bound artifact bytes near an ingress boundary.</td></tr><tr><td><code>Schedule</code></td><td><code>takoform_schedule</code></td><td><code>0.1.0</code></td><td>Portable cron lifecycle that invokes exactly one connected Resource.</td></tr><tr><td><code>ContainerService</code></td><td><code>takoform_container_service</code></td><td><code>0.1.0</code></td><td>Portable service executed from an immutable OCI image digest.</td></tr><tr><td><code>StatefulEntity</code></td><td><code>takoform_stateful_entity</code></td><td><code>0.1.0</code></td><td>Portable namespace of addressable persistent entities implemented by digest-bound application bytes.</td></tr></tbody></table><h2 id="data-and-storage" tabindex="-1">Data and storage <a class="header-anchor" href="#data-and-storage" aria-label="Permalink to &quot;Data and storage&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Kind</th><th>Resource</th><th>Version</th><th>Portable intent</th></tr></thead><tbody><tr><td><code>RelationalDatabase</code></td><td><code>takoform_relational_database</code></td><td><code>0.1.0</code></td><td>Portable relational database identified by an open engine capability token.</td></tr><tr><td><code>ObjectBucket</code></td><td><code>takoform_object_bucket</code></td><td><code>0.1.0</code></td><td>Portable object storage namespace.</td></tr><tr><td><code>KeyValueStore</code></td><td><code>takoform_key_value_store</code></td><td><code>0.1.0</code></td><td>Portable key/value state with declared consistency and expiry semantics.</td></tr><tr><td><code>Queue</code></td><td><code>takoform_queue</code></td><td><code>0.1.0</code></td><td>Portable asynchronous at-least-once message delivery.</td></tr><tr><td><code>VectorIndex</code></td><td><code>takoform_vector_index</code></td><td><code>0.1.0</code></td><td>Portable vector index with dimensions fixed for the index lifecycle.</td></tr></tbody></table><h2 id="declared-runtime-interfaces" tabindex="-1">Declared runtime interfaces <a class="header-anchor" href="#declared-runtime-interfaces" aria-label="Permalink to &quot;Declared runtime interfaces&quot;">​</a></h2><p>A Form may declare the runtime interfaces its service exposes. The names are author-defined and open: there is no registry, no allowlist, and no central approval. A declaration states what exists and how its non-secret values are filled; the host creates the record, authorizes consumers, and owns its lifecycle.</p><table tabindex="0"><thead><tr><th>Kind</th><th>Interface</th></tr></thead><tbody><tr><td><code>EdgeWorker</code></td><td><code>http.request@1</code> (request)</td></tr><tr><td><code>RelationalDatabase</code></td><td><code>sql.query@1</code> (execute, query, transaction)</td></tr><tr><td><code>ObjectBucket</code></td><td><code>object.storage@1</code> (delete, get, list, put)</td></tr><tr><td><code>KeyValueStore</code></td><td><code>keyvalue.store@1</code> (delete, get, list, put)</td></tr><tr><td><code>Queue</code></td><td><code>queue.messages@1</code> (acknowledge, receive, send)</td></tr><tr><td><code>ContainerService</code></td><td><code>http.request@1</code> (request)</td></tr><tr><td><code>StatefulEntity</code></td><td><code>entity.invoke@1</code> (invoke)</td></tr><tr><td><code>VectorIndex</code></td><td><code>vector.query@1</code> (delete, query, upsert)</td></tr></tbody></table><h2 id="immutable-fields" tabindex="-1">Immutable fields <a class="header-anchor" href="#immutable-fields" aria-label="Permalink to &quot;Immutable fields&quot;">​</a></h2><p>Every Form fixes its <code>/name</code>. A Form that additionally fixes a field states so in its definition, and the provider enforces replacement for exactly those fields; the protocol lifecycle proves both.</p><table tabindex="0"><thead><tr><th>Kind</th><th>Immutable</th></tr></thead><tbody><tr><td><code>EdgeWorker</code></td><td><code>/name</code></td></tr><tr><td><code>RelationalDatabase</code></td><td><code>/databaseName</code>, <code>/engine</code>, <code>/name</code></td></tr><tr><td><code>ObjectBucket</code></td><td><code>/name</code></td></tr><tr><td><code>KeyValueStore</code></td><td><code>/name</code></td></tr><tr><td><code>Queue</code></td><td><code>/name</code></td></tr><tr><td><code>Schedule</code></td><td><code>/name</code></td></tr><tr><td><code>ContainerService</code></td><td><code>/name</code></td></tr><tr><td><code>StatefulEntity</code></td><td><code>/name</code></td></tr><tr><td><code>VectorIndex</code></td><td><code>/dimensions</code>, <code>/name</code></td></tr></tbody></table><h2 id="status" tabindex="-1">Status <a class="header-anchor" href="#status" aria-label="Permalink to &quot;Status&quot;">​</a></h2><p>Every entry in this inventory is an unpublished <code>0.1.0</code> candidate. Takosumi Cloud implementation is workload and first-host evidence only; it does not turn a Proposal into a portable standard or authorize publication.</p><p>The earlier ten-package generation is also retired, not erased. Its immutable bytes and admission evidence stay verifiable through <a href="retired-package-set.json"><code>retired-package-set.json</code></a>. Neither retained set may be rewritten, re-signed, promoted, or used to derive a current approved subset. Current lifecycle truth comes only from <a href="lifecycle.json"><code>lifecycle.json</code></a>; Host Support and activation remain separate host-owned facts.</p>',16)])])}const p=t(r,[["render",c]]);export{m as __pageData,p as default};
